always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        out_valid <= 1'b0;
        out_cnt   <= 6'd0;
    end else begin
        out_valid <= 1'b0;
        out_cnt  <= 6'd0;
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        out_data  <= 20'd0;
    end else if (out_valid ) begin
        out_data <= mat_c[out_cnt[5:3]][out_cnt[2:0]];
    end else begin
        out_data <= 20'd0;
    end
end

